112	/// drive_one_engine -- materialisiert eine reale Komposition als IObservableTier (CEB-Pfad-Form), faehrt das
113	/// Pruefdock-Konformitaets-Gate (std::map-Oracle) und misst danach die per-Op-Latenzen ueber
114	/// ExecuteEngineCommand (-> ExecutionResult::latency_samples_ns). C = die reale Katalog-Komposition.
115	template <class C>
116	[[nodiscard]] inline cmd::ExecutionResult drive_one_engine(std::string_view engine_name, cmd::Workload const& workload,
117	                                                           std::uint64_t& conformance_cases, bool& conformance_passed) {
118	    using AnatomyT = an::SearchAlgorithmAnatomy<C>;
119	    an::SearchAlgorithmAbiAdapter<AnatomyT> tier; // == COMDARE_DEFINE_ANATOMY_MODULE-Adapter, hier in-process (INERT)
120	    auto* obs = dynamic_cast<an::IObservableTier*>(static_cast<an::IAnatomyBase*>(&tier));
121	
122	    // (Pruefdock) Konformitaets-Gate VOR der Messung: die Gattungs-Huelle gegen std::map<uint64,uint64> als Oracle.
123	    auto const cg      = pd::run_conformance_gate(*obs); // IObservableTier IS-A IDriveableTier
124	    conformance_cases  = cg.cases_total;
125	    conformance_passed = cg.passed();
126	    obs->tier_clear(); // frischer Zustand fuer den Mess-Lauf (das Gate hat das Tier befuellt/geleert)
127	
128	    KatalogTierEngineCallable callable{*obs};
129	    cmd::ExecuteEngineCommand cmd_engine(engine_name, workload, callable);
130	    cmd_engine.execute(); // timet jeden callable-Aufruf -> latency_samples_ns aus dem REALEN Tier
131	    return cmd_engine.result();
132	}
